import{_ as p,r as o,o as c,c as d,e as l,a,s as r,t as n}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Фрагменты (Чанки, Partials) - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Отображение фрагментов","slug":"отображение-фрагментов","link":"#отображение-фрагментов","children":[]},{"level":2,"title":"Передача переменных во фрагменты","slug":"передача-переменных-во-фрагменты","link":"#передача-переменных-во-фрагменты","children":[]},{"level":2,"title":"Динамические фрагменты","slug":"динамические-фрагменты","link":"#динамические-фрагменты","children":[{"level":3,"title":"Жизненный цикл фрагментов","slug":"жизненныи-цикл-фрагментов","link":"#жизненныи-цикл-фрагментов","children":[]},{"level":3,"title":"Ограничения жизненного цикла","slug":"ограничения-жизненного-цикла","link":"#ограничения-жизненного-цикла","children":[]}]}],"relativePath":"1.x/ru/cms/partials.md","filePath":"1.x/ru/cms/partials.md"}'),h={name:"1.x/ru/cms/partials.md"};function u(t,e,m,g,_,f){const s=o("pre-heading"),i=o("post-heading");return c(),d("div",null,[l(s),e[0]||(e[0]=a("h1",null,"Фрагменты (Чанки, Partials)",-1)),l(i),e[1]||(e[1]=r(`<p><a name="introduction"></a></p><h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>Фрагментыx - это небольшой кусок Twig разметки, который можно многократно использовать в любом месте сайта (на разных страницах или макетах). Хорошим примером фрагмента является подвал сайта, который отображается на всех страницах. Кроме того, они необходимы для обновления содержимого страницы при помощи <a href="./../cms/ajax.html">AJAX</a>.</p><p>Фрагменты находятся в папке <strong>/partials</strong> темы и должны иметь расширение <strong>htm</strong>. Пример простого фрагмента:</p><pre><code>&lt;p&gt;This is a partial&lt;/p&gt;
</code></pre><p><a href="./../cms/themes.html#configuration-section">Раздел Конфигурации</a> необязателен для фрагментов и может содержать параметр <strong>description</strong>, который отображается в административной части сайта, а также параметры компонентов. Далее представлен пример фрагмента с описанием:</p><pre><code>description = &quot;Demo partial&quot;
==
&lt;p&gt;This is a partial&lt;/p&gt;
</code></pre><p><a name="rendering-partials"></a></p><h2 id="отображение-фрагментов"><a href="#отображение-фрагментов" class="header-anchor">#</a> Отображение фрагментов</h2><p>Twig тег <code>{% partial &quot;partial-name&quot; %}</code> выводит фрагмент на страницу и имеет единственный обязательный параметр - название файла фрагмента без расширения. Если фрагмент находится в <a href="./../cms/themes.html#subdirectories">подпапке</a>, то Вы должны указать ее название. Тег <code>{% partial %}</code> можно использовать в страницах, шаблонах и других фрагментах. Пример использования фрагмента на странице:</p><pre><code>&lt;div class=&quot;sidebar&quot;&gt;
    {% partial &quot;sidebar-contacts&quot; %}
&lt;/div&gt;
</code></pre><p><a name="partial-variables"></a></p><h2 id="передача-переменных-во-фрагменты"><a href="#передача-переменных-во-фрагменты" class="header-anchor">#</a> Передача переменных во фрагменты</h2><p>Вам потребуется часто передавать переменные во фрагменты. Например, чтобы отфильтровать список записей в блоге по категории. Для этого нужно указать их после названия фрагмента. Пример:</p><pre><code>&lt;div class=&quot;sidebar&quot;&gt;
    {% partial &quot;blog-posts&quot; posts=posts %}
&lt;/div&gt;
</code></pre><p>Вы также можете задать свои переменные:</p><pre><code>&lt;div class=&quot;sidebar&quot;&gt;
    {% partial &quot;sidebar-contacts&quot; city=&quot;Vancouver&quot; country=&quot;Canada&quot; %}
&lt;/div&gt;
</code></pre><p>Внутри фрагмента доступ к переменным осуществляется как и везде:</p>`,18)),a("pre",null,[a("code",null,"<p>Country: "+n(t.country)+", city: "+n(t.city)+`.</p>
`,1)]),e[2]||(e[2]=r(`<p><a name="dynamic-partials"></a></p><h2 id="динамические-фрагменты"><a href="#динамические-фрагменты" class="header-anchor">#</a> Динамические фрагменты</h2><p>Фрагменты, как и страницы, могут использовать любые возможности Twig (см. <a href="./pages.html#dynamic-pages">Динамические страницы</a>).</p><p><a name="partial-life-cycle"></a></p><h3 id="жизненныи-цикл-фрагментов"><a href="#жизненныи-цикл-фрагментов" class="header-anchor">#</a> Жизненный цикл фрагментов</h3><p>Существуют специальные функции, которые могут быть указаны в Разделе PHP фрагментов: <code>onStart()</code> и <code>onEnd()</code>. Функция <code>onStart()</code> выполняется перед тем как фрагмент будет отображен на странице и перед тем как фрагменты компонентов <a href="./components.html">./components</a> будут отображены. Функция <code>onEnd()</code> выполняется перед тем как фрагмент будет отображен на странице, но после того как рагменты компонентов <a href="./components.html">./components</a> будут отображены. В этих функциях, например, Вы можете задать переменные для отображения:</p><div class="language- extra-class"><pre class="language-text"><code>==
function onStart()
{
    $this[&#39;hello&#39;] = &quot;Hello world!&quot;;
}
==
&lt;h3&gt;{{ hello }}&lt;/h3&gt;
</code></pre></div><p>Язык разметки, используемый в October, описан в <a href="./../markup.html">Руководстве по разметке</a>. Последовательность вызовов обработчиков описана в <a href="./../cms/layouts.html#dynamic-layouts">Динамических макетах</a>.</p><p><a name="life-cycle-limitations"></a></p><h3 id="ограничения-жизненного-цикла"><a href="#ограничения-жизненного-цикла" class="header-anchor">#</a> Ограничения жизненного цикла</h3><p>Фрагменты отображаются по мере загрузки страницы. Поэтому есть некоторые ограничения:</p><ol><li>События AJAX не будту работать нормально во фрагментах.</li><li>Функции <code>onStart()</code> и <code>onEnd()</code> не могут возвращать значения.</li><li>Обработка форм происходит во время отображения фрагментов.</li></ol><p>Поэтому, в основном, их лучше использовать только для отображения простого кода.</p>`,13))])}const T=p(h,[["render",u]]);export{v as __pageData,T as default};
